// Nama   : TambahHariKerja
// Tujuan : menghitung hari selesai setelah n hari kerja (Senin-Jumat)
// Input  : hariMulai (INTEGER, 1 = Senin ... 7 = Minggu), n (INTEGER >= 0)
// Output : nomor hari selesai (1..7)
// Uji    : (5, 1) -> 1   Jumat + 1 hari kerja = Senin
//          (1, 5) -> 1   Senin + 5 hari kerja = Senin berikutnya
//          (4, 3) -> 2   Kamis + 3 hari kerja = Selasa
FUNCTION TambahHariKerja(hariMulai : INTEGER, n : INTEGER) RETURNS INTEGER
    DECLARE hari : INTEGER
    hari ← hariMulai
    WHILE n > 0 DO
        hari ← hari MOD 7 + 1        // 7 (Minggu) kembali ke 1 (Senin)
        IF hari <= 5 THEN            // hanya Senin-Jumat yang dihitung
            n ← n - 1
        ENDIF
    ENDWHILE
    RETURN hari
ENDFUNCTION

